import 'package:flutter/material.dart';
import 'package:supabase_flutter/supabase_flutter.dart';
import '../../data/remote/supabase_service.dart';
class LoginPage extends StatefulWidget{const LoginPage({super.key});@override State<LoginPage> createState()=>_LoginPageState();}
class _LoginPageState extends State<LoginPage>{final email=TextEditingController(),password=TextEditingController();bool loading=false;String? error;
Future<void> submit(bool signup)async{final c=SnoteSupabase.client;if(c==null)return;setState(()=>{loading=true;error=null;});try{final r=signup?await c.auth.signUp(email:email.text.trim(),password:password.text):await c.auth.signInWithPassword(email:email.text.trim(),password:password.text);if(signup&&r.session==null)error='Check your email to confirm the account.';}on AuthException catch(e){error=e.message;}catch(e){error=e.toString();}finally{if(mounted)setState(()=>loading=false);}}
@override Widget build(BuildContext context)=>Scaffold(body:Center(child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:430),child:Padding(padding:const EdgeInsets.all(24),child:Card(child:Padding(padding:const EdgeInsets.all(28),child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.edit_note,size:64),const SizedBox(height:16),const Text('Welcome to Snote',style:TextStyle(fontSize:28,fontWeight:FontWeight.bold)),const SizedBox(height:8),const Text('Sign in to sync your notebook across devices.',textAlign:TextAlign.center),const SizedBox(height:20),TextField(controller:email,keyboardType:TextInputType.emailAddress,decoration:const InputDecoration(labelText:'Email')),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'Password')),if(error!=null)Padding(padding:const EdgeInsets.only(top:12),child:Text(error!,style:TextStyle(color:Colors.red))),const SizedBox(height:20),Row(children:[Expanded(child:FilledButton(onPressed:loading?null:()=>submit(false),child:const Text('Sign in'))),const SizedBox(width:10),Expanded(child:OutlinedButton(onPressed:loading?null:()=>submit(true),child:const Text('Create account')))])]))))));}
}
